{"path": "gallery.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Pobrecita | Photo Gallery</title>
    <style>
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: #1a1a1a;
            color: #f5f5f5;
            min-height: 100vh;
        }
        header {
            text-align: center;
            padding: 3rem 1rem 2rem;
        }
        header h1 {
            font-size: 2.5rem;
            letter-spacing: 2px;
            margin-bottom: 0.5rem;
        }
        header p {
            color: #aaa;
            font-size: 1.1rem;
        }
        .gallery {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 1rem;
            padding: 1rem 2rem 3rem;
            max-width: 1400px;
            margin: 0 auto;
        }
        .gallery-item {
            position: relative;
            overflow: hidden;
            border-radius: 8px;
            cursor: pointer;
            background: #2a2a2a;
            aspect-ratio: 1 / 1;
        }
        .gallery-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.3s ease, opacity 0.3s ease;
        }
        .gallery-item:hover img {
            transform: scale(1.05);
            opacity: 0.85;
        }
        .gallery-item .caption {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            padding: 1rem;
            background: linear-gradient(transparent, rgba(0,0,0,0.8));
            transform: translateY(100%);
            transition: transform 0.3s ease;
        }
        .gallery-item:hover .caption {
            transform: translateY(0);
        }
        .lightbox {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.95);
            justify-content: center;
            align-items: center;
            z-index: 1000;
        }
        .lightbox.active {
            display: flex;
        }
        .lightbox img {
            max-width: 90%;
            max-height: 85%;
            border-radius: 8px;
            box-shadow: 0 0 40px rgba(0,0,0,0.5);
        }
        .lightbox-close,
        .lightbox-prev,
        .lightbox-next {
            position: absolute;
            background: rgba(255,255,255,0.1);
            border: none;
            color: #fff;
            font-size: 2rem;
            width: 50px;
            height: 50px;
            border-radius: 50%;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s ease;
        }
        .lightbox-close:hover,
        .lightbox-prev:hover,
        .lightbox-next:hover {
            background: rgba(255,255,255,0.25);
        }
        .lightbox-close {
            top: 20px;
            right: 20px;
        }
        .lightbox-prev {
            left: 20px;
            top: 50%;
            transform: translateY(-50%);
        }
        .lightbox-next {
            right: 20px;
            top: 50%;
            transform: translateY(-50%);
        }
        .lightbox-caption {
            position: absolute;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            color: #ccc;
            font-size: 1.1rem;
            text-align: center;
            max-width: 80%;
        }
        footer {
            text-align: center;
            padding: 2rem;
            color: #777;
        }
        @media (max-width: 600px) {
            .gallery {
                padding: 1rem;
            }
            .lightbox-prev,
            .lightbox-next {
                display: none;
            }
        }
    </style>
</head>
<body>

    <header>
        <h1>Pobrecita</h1>
        <p>A photo gallery</p>
    </header>

    <main class="gallery" id="gallery"></main>

    <div class="lightbox" id="lightbox">
        <button class="lightbox-close" id="lightbox-close">&times;</button>
        <button class="lightbox-prev" id="lightbox-prev">&#10094;</button>
        <img src="" alt="" id="lightbox-img">
        <button class="lightbox-next" id="lightbox-next">&#10095;</button>
        <div class="lightbox-caption" id="lightbox-caption"></div>
    </div>

    <footer>
        &copy; Pobrecita Gallery. All rights reserved.
    </footer>

    <script>
        const photos = [
            { src: 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80', caption: 'Mountain sunrise' },
            { src: 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&q=80', caption: 'Rolling hills' },
            { src: 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&q=80', caption: 'Calm lake' },
            { src: 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=800&q=80', caption: 'Forest path' },
            { src: 'https://images.unsplash.com/photo-1433086966358-54859d0ed716?w=800&q=80', caption: 'Waterfall' },
            { src: 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', caption: 'Ocean beach' },
            { src: 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?w=800&q=80', caption: 'Autumn leaves' },
            { src: 'https://images.unsplash.com/photo-1504198458649-3128b932f49e?w=800&q=80', caption: 'Desert dunes' },
            { src: 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&q=80', caption: 'Misty valley' }
        ];

        const gallery = document.getElementById('gallery');
        const lightbox = document.getElementById('lightbox');
        const lightboxImg = document.getElementById('lightbox-img');
        const lightboxCaption = document.getElementById('lightbox-caption');
        let currentIndex = 0;

        photos.forEach((photo, index) => {
            const item = document.createElement('div');
            item.className = 'gallery-item';
            item.innerHTML = `
                <img src="${photo.src}" alt="${photo.caption}" loading="lazy">
                <div class="caption">${photo.caption}</div>
            `;
            item.addEventListener('click', () => openLightbox(index));
            gallery.appendChild(item);
        });

        function openLightbox(index) {
            currentIndex = index;
            updateLightbox();
            lightbox.classList.add('active');
        }

        function closeLightbox() {
            lightbox.classList.remove('active');
        }

        function updateLightbox() {
            lightboxImg.src = photos[currentIndex].src;
            lightboxCaption.textContent = photos[currentIndex].caption;
        }

        function nextImage() {
            currentIndex = (currentIndex + 1) % photos.length;
            updateLightbox();
        }

        function prevImage() {
            currentIndex = (currentIndex - 1 + photos.length) % photos.length;
            updateLightbox();
        }

        document.getElementById('lightbox-close').addEventListener('click', closeLightbox);
        document.getElementById('lightbox-next').addEventListener('click', nextImage);
        document.getElementById('lightbox-prev').addEventListener('click', prevImage);

        lightbox.addEventListener('click', (e) => {
            if (e.target === lightbox) closeLightbox();
        });

        document.addEventListener('keydown', (e) => {
            if (!lightbox.classList.contains('active')) return;
            if (e.key === 'Escape') closeLightbox();
            if (e.key === 'ArrowRight') nextImage();
            if (e.key === 'ArrowLeft') prevImage();
        });
    </script>

</body>
</html>
